parameters.jsCode:
const categories = ['client', 'facture', 'rendez-vous', 'newsletter', 'spam probable', 'autre'];
const input = $('IA tentative 1').item.json;
const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';

let p = null;
try { p = JSON.parse(content); } catch (e) { p = null; }

if (!p || typeof p !== 'object') {
  // Keep the source email so the second attempt can reuse it.
  return [{ json: {
    retry: true,
    emailId: input.emailId,
    subject: input.subject || '',
    sender: input.sender || '',
    body: input.body || ''
  } }];
}

const validCategory = categories.includes(p.category);
const category = validCategory ? p.category : 'autre';
const priority = [1, 2, 3].includes(p.priority) ? p.priority : 1;
const summary = (typeof p.summary === 'string' && p.summary.trim())
  ? p.summary.trim().slice(0, 500)
  : 'Classification incomplète. À vérifier manuellement.';
const expectedAction = (typeof p.expectedAction === 'string' && p.expectedAction.trim())
  ? p.expectedAction.trim().slice(0, 500)
  : 'À vérifier manuellement.';
const needsReview = !validCategory || !p.summary || !p.expectedAction;

return [{ json: { retry: false, emailId: input.emailId, category, priority, summary, expectedAction, needsReview } }];

